CREATE OR REPLACE FUNCTION public.biz_step_scope_ok(_steps jsonb,_index int,_actor uuid,_owner uuid,_dept uuid,_at timestamptz) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT public.is_super_admin(_actor) OR public.biz_scope_ok(_actor,_owner,_dept,_at) OR ((_steps->_index->>'type'='user' OR _steps->_index->>'substitute_id'=_actor::text) AND (_steps->_index->>'user_id'=_actor::text OR _steps->_index->>'substitute_id'=_actor::text) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=_actor AND status='Đang hoạt động'))$$;
